 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; # [doc = " Iterates through the AST, extracts individual declarations, and writes them to separate files."] # [doc = " Returns a vector of Identifiers for the collected module names."] pub fn extract_and_write_declarations (syntax_tree : & syn :: File , paths : & CratePaths , config : & SplitDeclsConfig , dry_run : bool , common_uses : TokenStream ,) -> Result < Vec < Ident > > { let mut collected_module_names : Vec < Ident > = Vec :: new () ; let mut item_count = 0 ; for item in & syntax_tree . items { let extracted_decl = match item { Item :: Fn (item_fn) => Some (ExtractedDecl { name : item_fn . sig . ident . to_string () , kind : "fn" . to_string () , content : item_fn . to_token_stream () , }) , Item :: Struct (item_struct) => Some (ExtractedDecl { name : item_struct . ident . to_string () , kind : "struct" . to_string () , content : item_struct . to_token_stream () , }) , Item :: Enum (item_enum) => Some (ExtractedDecl { name : item_enum . ident . to_string () , kind : "enum" . to_string () , content : item_enum . to_token_stream () , }) , Item :: Const (item_const) => Some (ExtractedDecl { name : item_const . ident . to_string () , kind : "const" . to_string () , content : item_const . to_token_stream () , }) , Item :: Static (item_static) => Some (ExtractedDecl { name : item_static . ident . to_string () , kind : "static" . to_string () , content : item_static . to_token_stream () , }) , Item :: Trait (item_trait) => Some (ExtractedDecl { name : item_trait . ident . to_string () , kind : "trait" . to_string () , content : item_trait . to_token_stream () , }) , Item :: Impl (item_impl) => { let name = if let Some ((_ , path , _)) = & item_impl . trait_ { format ! ("impl_for_{}" , path . to_token_stream () . to_string () . replace ("::" , "_")) } else if let syn :: Type :: Path (type_path) = & * item_impl . self_ty { if let Some (segment) = type_path . path . segments . last () { format ! ("impl_for_{}" , segment . ident . to_string ()) } else { format ! ("impl_{}" , item_count) } } else { format ! ("impl_{}" , item_count) } ; Some (ExtractedDecl { name , kind : "impl" . to_string () , content : item_impl . to_token_stream () , }) } , Item :: Type (item_type) => Some (ExtractedDecl { name : item_type . ident . to_string () , kind : "type" . to_string () , content : item_type . to_token_stream () , }) , Item :: Union (item_union) => Some (ExtractedDecl { name : item_union . ident . to_string () , kind : "union" . to_string () , content : item_union . to_token_stream () , }) , Item :: Use (item_use) => { println ! ("Skipping top-level use statement in splitting: {}" , item_use . to_token_stream ()) ; None } , Item :: Macro (item_macro) => { println ! ("Including top-level macro invocation: {}" , item_macro . mac . path . to_token_stream ()) ; None } , Item :: Mod (item_mod) => { println ! ("Skipping top-level module: {}" , item_mod . ident) ; None } _ => { println ! ("Skipping unsupported item type: {}" , item . to_token_stream ()) ; None } } ; if let Some (decl) = extracted_decl { let module_name_str = format ! ("{}_decls_{}" , paths . crate_name . replace ("-" , "_") , decl . name) ; let module_name_ident = Ident :: new (& module_name_str , Span :: call_site ()) ; collected_module_names . push (module_name_ident . clone ()) ; let decl_file_path = paths . decls_output_dir . join (format ! ("{}.rs" , module_name_str)) ; let custom_prelude = if let Some (ref prelude_str) = config . custom_prelude_overlay { prelude_str . parse :: < TokenStream > () . map_err (| e | anyhow :: anyhow ! ("Failed to parse custom prelude overlay: {}" , e)) ? } else { quote ! { } } ; let attributed_decl_content = quote ! { # [decl_ # module_name_ident] # decl . content } ; let file_content = quote ! { # custom_prelude # common_uses prelude ! { } # attributed_decl_content } ; if ! dry_run { fs :: write (& decl_file_path , file_content . to_string ()) . context (format ! ("Failed to write to {}" , decl_file_path . display ())) ? ; println ! ("Split '{} {}' to {}" , decl . kind , decl . name , decl_file_path . display ()) ; } else { println ! ("Dry-run: Would split '{} {}' to {}" , decl . kind , decl . name , decl_file_path . display ()) ; } } item_count += 1 ; } Ok (collected_module_names) }